head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDFIS00400_07.xml";
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 조회조건 결산일자

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    // 결산일자 조회
    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_InsideNrealzProft.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd == "" || scwin.vAcntclsDt == "") {
        return false;
    }
    return true;
};


/**
 * 내부미실현손익 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_InsideNrealzProft);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.insideNrealzProft" + "&outputMessageId=FIS_INSIDE_NREALZ_PROFT" + "&param01=" + scwin.vKisCd + "&param02=" + scwin.vAcntclsDt;
    dts_InsideNrealzProft.DataID = encodeURI(url);
    dts_InsideNrealzProft.Reset();
};
scwin.btn_Excel_onclick = function() {
    if (dts_InsideNrealzProft.getTotalRow() <= 0) {
        $c.win.alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_InsideNrealzProft, "내부미실현손익", "", "8");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_InsideNrealzProft_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_InsideNrealzProft);
    $c.stf.alert_error(dts_InsideNrealzProft);
};
scwin.dts_InsideNrealzProft_OnLoadCompleted = function(rowcount) {
    if (dts_InsideNrealzProft.errorMsg) {
        $c.win.alert(dts_InsideNrealzProft.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_InsideNrealzProft);
};
